        //
        //     {
        //         "data": null,
        //         "error": "NOT_ONBOARDED",
        //         "message": "User has never called /onboarding endpoint"
        //     }
        //
        //     {
        //         "error": "INVALID_REQUEST_PARAMETER",
        //         "message": "market: FOO-USD-PERP does not exist.",
        //         "data": { "market": "FOO-USD-PERP does not exist." }
        //     }
